import{_ as o,o as t,c as r,U as l}from"./chunks/framework.CYN6H5OD.js";const u=JSON.parse('{"title":"Release Notes","description":"","frontmatter":{},"headers":[],"relativePath":"release-notes.md","filePath":"release-notes.md"}'),i={name:"release-notes.md"};function s(n,e,a,d,c,g){return t(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="release-notes" tabindex="-1">Release Notes <a class="header-anchor" href="#release-notes" aria-label="Permalink to &quot;Release Notes&quot;">​</a></h1><div class="lead"><p>All release notes can be found through <a href="https://github.com/ahmadfajar/vue-mdbootstrap/releases" target="_blank" rel="noreferrer">GitHub</a> and can be viewed below for your convenience.</p></div><h2 id="v2-2-1" tabindex="-1">v2.2.1 <a class="header-anchor" href="#v2-2-1" aria-label="Permalink to &quot;v2.2.1&quot;">​</a></h2><p>Released: March 20, 2026</p><h3>Features &amp; Improvements</h3><ul><li><strong>BsButton</strong>: improve CSS variables and color variants.</li><li><strong>BsColorPicker</strong>: <ul><li>Add property <code>mode-button-tonal</code>.</li><li>Improve input fields.</li></ul></li><li><strong>BsDivider</strong>: improve color when <code>dark</code> property is defined.</li><li><strong>BsFontawesomeIcon</strong>: <ul><li>Update the valid value of <code>variant</code> property to <code>solid</code>, <code>regular</code> and <code>brands</code>. See <a href="https://fontawesome.com/search?ic=free-collection" target="_blank" rel="noreferrer">Font Awesome</a> free icons documentation for details.</li><li>Change resource url to github because the official website is now blocked for CDN.</li><li>Update the value of <code>version</code> property to <code>7.2.0</code>.</li></ul></li><li><strong>BsProgressBar</strong>: <ul><li>Make CSS classes more consistent.</li><li>Improve CSS variables.</li><li>Small improvement on rendering HTML.</li></ul></li><li><strong>BsSwitch</strong>: <ul><li>Add property <code>variant</code> to change the component style appearance.</li><li>Mark properties: <code>inset-mode</code> and <code>inset-outlined</code> as <strong>deprecated</strong>, use <code>variant</code> property instead.</li></ul></li><li><strong>BsTabs</strong>: improve vertical tabs.</li><li><strong>BsToggleButton</strong>: improve active button border color when property <code>multiple</code> is set to <code>true</code>.</li><li><strong>BsTooltip</strong>: improve <code>background-color</code> on dark theme.</li></ul><h3>Bug Fixes</h3><ul><li><strong>BsButton</strong>: fixed bug where the CSS <code>background-color</code> and <code>border</code> were not working properly.</li><li><strong>BsDatePicker</strong>: fixed calendar table CSS rules break on VitePress.</li><li><strong>BsListbox</strong>, <strong>BsSearchField</strong>: fixed input field CSS breaks on VitePress.</li><li><strong>BsListNav</strong>: fixed CSS layout breaks on VitePress.</li><li><strong>BsTabs</strong>: fixed bug where the <code>color</code> property wasn&#39;t working properly when the <code>variant</code> property was set with a custom value.</li><li><strong>BsTextArea</strong>, <strong>BsTextField</strong>: fixed CSS layout breaks on VitePress.</li><li><strong>BsToggleField</strong>: fixed bug property <code>pillOff</code> not working properly.</li></ul><h2 id="v2-2-0" tabindex="-1">v2.2.0 <a class="header-anchor" href="#v2-2-0" aria-label="Permalink to &quot;v2.2.0&quot;">​</a></h2><p>Released: February 02, 2026</p><h3>Features &amp; Improvements</h3><ul><li>Add support for <strong>Bootstrap v5.3</strong> and <strong>TailwindCSS v4.1</strong>.</li><li>Add support for dark theme.</li><li>Add CSS utility classes.</li><li>Create global CSS variables for UI color consistency.</li><li>Convert all <code>rgb</code> and <code>hex</code> css color to <code>oklch</code> and improve scss mixin.</li><li>Improve components CSS rules, utilize css <code>@layer</code> and make it compatible with TailwindCSS.</li><li>New components: <strong>BsCloseButton</strong>, <strong>BsSpinLoader</strong>.</li><li><strong>BsAlert</strong>: <ul><li>Decouple from Bootstrap alert CSS.</li><li>Add property <code>closeButtonColor</code>.</li><li>Improve close button.</li><li>Improve color variants.</li></ul></li><li><strong>BsBadge</strong>: <ul><li>Decouple from Bootstrap badge CSS.</li><li>Remove default value from <code>color</code> property.</li></ul></li><li><strong>BsBreadcrumb</strong>: <ul><li>Decouple from Bootstrap breadcrumb CSS.</li><li>Small improvement.</li></ul></li><li><strong>BsButton</strong>: <ul><li>Decouple from Bootstrap button CSS.</li><li>Add properties: <code>iconClass</code> and <code>pillOff</code>.</li><li>Provide <code>data-*</code> attributes when rendering HTML.</li><li>Improve color variants.</li><li>Improve CSS variables.</li></ul></li><li><strong>BsCard</strong>, <strong>BsCardBody</strong>, <strong>BsCardContent</strong>, <strong>BsCardFooter</strong>, <strong>BsCardHeader</strong>: <ul><li>Decouple from Bootstrap card CSS.</li><li>Integrate with global CSS variables.</li></ul></li><li><strong>BsCardMedia</strong>: <ul><li>Decouple from Bootstrap card CSS.</li><li>Add slots: <code>title</code> and <code>subtitle</code>.</li></ul></li><li><strong>BsCheckbox</strong>, <strong>BsRadio</strong>, <strong>BsSwitch</strong>: <ul><li>Provide <code>data-*</code> attributes when rendering html.</li></ul></li><li><strong>BsCheckboxGroup</strong>, <strong>BsRadioGroup</strong>: <ul><li>Add property <code>persistentHelpOff</code>.</li></ul></li><li><strong>BsChip</strong>: <ul><li>Add property <code>closeButtonColor</code>.</li><li>Provide <code>data-*</code> attributes when rendering HTML.</li><li>Improve close button.</li><li>Improve color variants.</li></ul></li><li><strong>BsChipField</strong>: <ul><li>Add property <code>persistentHelpOff</code>.</li><li>Provide <code>data-*</code> attributes when rendering HTML.</li><li>Correctly set chips to readonly when the field is in readonly state.</li></ul></li><li><strong>BsChipGroup</strong>: add property <code>closeButtonColor</code>.</li><li><strong>BsColorPicker</strong>: <ul><li>Add support <code>oklch</code> color space.</li><li>Add <code>oklch</code> to toggle button.</li><li>Mark <code>containerColor</code> property as <strong>deprecated</strong> and remove its default value.</li><li>Enable change the value via input box.</li><li>Improve swatch container and buttons.</li><li>Improve sync between color preview and value.</li><li>Improve exposed methods.</li></ul></li><li><strong>BsCombobox</strong>: <ul><li>Add properties: <code>itemSeparatorDark</code>, <code>persistentHelpOff</code>.</li><li>Mark <code>listboxColor</code> property as deprecated.</li><li>Correctly set chips to readonly when the field is in readonly state.</li><li>Provide <code>data-*</code> attributes when rendering HTML.</li><li>Improve focus and disable state.</li><li>Integrate with global CSS variables.</li></ul></li><li><strong>BsContent</strong>, <strong>BsApp</strong>, <strong>BsAppBar</strong>: <ul><li>Improve rendering the HTML.</li><li>Integrate with global CSS variables.</li></ul></li><li><strong>BsDatePicker</strong>: <ul><li>Add properties: <code>buttonColor</code>, <code>selectedColor</code>, <code>surfaceClass</code>.</li><li>Mark <code>surfaceColor</code> property as deprecated and remove its default value.</li><li>Integrate with global CSS variables.</li></ul></li><li><strong>BsDateTimeField</strong>: <ul><li>Add properties: <code>pickerButton</code>, <code>pickerSelectedColor</code>, <code>surfaceCls</code>, <code>persistentHelpOff</code>.</li><li>Mark <code>pickerColor</code> property as deprecated and remove its default value.</li><li>Provide <code>data-*</code> attributes when rendering HTML.</li><li>Improve focus state.</li><li>Integrate with global CSS variables.</li></ul></li><li><strong>BsDivider</strong>: adjusts width to fit the container width.</li><li><strong>BsDropdownMenu</strong>: integrate with global CSS variables.</li><li><strong>BsIcon</strong>: add property <code>svgClass</code>.</li><li><strong>BsListbox</strong>: <ul><li>Add property <code>itemSeparatorDark</code>.</li><li>Improve focus and disable state.</li><li>Integrate with global CSS variables.</li></ul></li><li><strong>BsLightbox</strong>: <ul><li>Add support for video and YouTube.</li><li>Improve <code>thumbnailHeight</code> property implementation.</li><li>Fixed dropdown-menus didn&#39;t display correctly.</li></ul></li><li><strong>BsListView</strong>, <strong>BsListTile</strong>, <strong>BsListNav</strong>: <ul><li>Integrate with global css variables.</li></ul></li><li><strong>BsMaskLoader</strong>, <strong>BsProgressBar</strong>: <ul><li>Decouple from Bootstrap CSS.</li><li>Small improvement.</li></ul></li><li><strong>BsModal</strong>: <ul><li>Improve inner body height when <code>scrollable</code> and <code>fullPage</code> is defined.</li><li>Fix modal is closed when the modal dialog body is clicked.</li><li>Integrate with global CSS variables.</li></ul></li><li><strong>BsNotification</strong>: improve close button.</li><li><strong>BsNumericField</strong>, <strong>BsTextField</strong>, <strong>BsTextArea</strong>: <ul><li>Add property <code>persistentHelpOff</code>.</li><li>Provide <code>data-*</code> attributes when rendering html.</li></ul></li><li><strong>BsPopover</strong>: <ul><li>Improve animation transition and scroll event.</li><li>Integrate with global CSS variables.</li></ul></li><li><strong>BsSearchField</strong>: add property <code>popoverOpen</code>.</li><li><strong>BsSvgIcon</strong>: add property <code>size</code>.</li><li><strong>BsSideDrawer</strong>: <ul><li>Mark <code>color</code> property as deprecated.</li><li>Improve rendering html.</li><li>Integrate with global CSS variables.</li></ul></li><li><strong>BsTabs</strong>: <ul><li>Decouple from Bootstrap CSS.</li><li>Add slot <code>append-header</code>.</li><li>Small improvement.</li></ul></li><li><strong>BsToggleButton</strong>: <ul><li>Add properties: <code>pillOff</code>, <code>iconSize</code>.</li><li>Provide <code>data-*</code> attributes when rendering HTML.</li></ul></li><li><strong>BsToggleField</strong>: <ul><li>Add properties: <code>pillOff</code>, <code>iconSize</code>, <code>persistentHelpOff</code>.</li><li>Provide <code>data-*</code> attributes when rendering HTML.</li></ul></li><li><strong>BsTooltip</strong>: improve animation, inner padding, border radius and CSS variables.</li><li><strong>CacheManager</strong>: improve performance using sessionStorage if available</li></ul><h3>Breaking Changes</h3><ul><li><strong>BsAlert</strong>: remove deprecated properties: <code>iconType</code>, <code>solidFill</code>.</li><li><strong>BsButton</strong>: mark <code>pill</code> property as <strong>deprecated</strong>.</li><li><strong>BsCheckboxGroup</strong>, <strong>BsRadioGroup</strong>, <strong>BsChipField</strong>: <ul><li>Remove deprecated property <code>externalValidator</code>.</li><li>Mark <code>persistent-help-text</code> property as <strong>deprecated</strong>.</li></ul></li><li><strong>BsChip</strong>, <strong>BsChipGroup</strong>: remove deprecated property <code>imgPadding</code>.</li><li><strong>BsCombobox</strong>: <ul><li>Remove deprecated properties: <code>externalValidator</code>, <code>checkOptionColor</code>, <code>checkOptionPosition</code>, <code>popoverMaxHeight</code>, <code>popoverMinHeight</code>.</li></ul></li><li><strong>BsDateTimeField</strong>: <ul><li>Remove deprecated properties: <code>transition</code>, <code>externalValidator</code>.</li><li>Remove <code>flat</code> property.</li></ul></li><li><strong>BsIconSvg</strong> is deprecated, use <strong>BsSvgIcon</strong> instead.</li><li><strong>BsIconSpinner</strong> is deprecated, use <strong>BsSpinnerIcon</strong> instead.</li><li><strong>BsIconFontawesome</strong> is deprecated, use <strong>BsFontawesomeIcon</strong> instead.</li><li><strong>BsImageHolder</strong>: remove deprecated property <code>placeHolder</code>.</li><li><strong>BsLightbox</strong>: <ul><li>Remove unused properties: <code>overlayColor</code>, <code>overlayOpacity</code>.</li><li>Rename property <code>imageClass</code> to <code>viewerClass</code>.</li><li>Rename property <code>imageStyles</code> to <code>viewerStyles</code>.</li></ul></li><li><strong>BsNumericField</strong>: <ul><li>Remove deprecated property: <code>externalValidator</code>.</li><li>Remove properties: <code>spinButton</code>, <code>spinButtonPlacement</code>, <code>flat</code>.</li><li>Change the type of <code>actionButton</code> property to <code>string</code> to accommodate <strong>up/down</strong> and <strong>plus/minus</strong> buttons.</li><li>Mark <code>persistent-help-text</code> property as <strong>deprecated</strong>.</li></ul></li><li><strong>BsTextArea</strong>, <strong>BsTextField</strong>: <ul><li>Remove deprecated property <code>externalValidator</code>.</li><li>Remove <code>flat</code> property.</li><li>Mark <code>persistent-help-text</code> property as <strong>deprecated</strong>.</li></ul></li><li><strong>BsToggleButton</strong>: <ul><li>Remove <code>flat</code> property.</li><li>Mark <code>pill</code> property as <strong>deprecated</strong>.</li></ul></li><li><strong>BsToggleField</strong>: <ul><li>Remove deprecated property <code>externalValidator</code>.</li><li>Remove <code>flat</code> property.</li><li>Mark properties: <code>persistent-help-text</code> and <code>pill</code> as <strong>deprecated</strong>.</li></ul></li></ul><h2 id="v2-1-7" tabindex="-1">v2.1.7 <a class="header-anchor" href="#v2-1-7" aria-label="Permalink to &quot;v2.1.7&quot;">​</a></h2><p>Released: February 03, 2025</p><h3>Bug Fixes</h3><ul><li><strong>BsTextArea</strong>: fixed bug could not determine its height when <code>auto-grow</code> and <code>readonly</code> were enabled and the <code>model-value</code> wasn&#39;t empty.</li></ul><h2 id="v2-1-6" tabindex="-1">v2.1.6 <a class="header-anchor" href="#v2-1-6" aria-label="Permalink to &quot;v2.1.6&quot;">​</a></h2><p>Released: February 01, 2025</p><h3>Improvements</h3><ul><li><strong>BsButton</strong>: <ul><li>Improve inner element spacing and padding when <code>dropdown-toggle</code> is enabled.</li><li>Improve spacing between icon and caret when <code>default-slot</code> is <strong>empty</strong> or <strong>undefined</strong> and <code>dropdown-toggle</code> is enabled.</li></ul></li><li><strong>BsTooltip</strong>: improve show or hide animation timing.</li></ul><h3>Bug Fixes</h3><ul><li><strong>BsTab</strong>: fixed bug that caused <code>v-if</code> to not work as expected.</li></ul><h2 id="v2-1-5" tabindex="-1">v2.1.5 <a class="header-anchor" href="#v2-1-5" aria-label="Permalink to &quot;v2.1.5&quot;">​</a></h2><p>Released: December 30, 2024</p><h3>Improvements</h3><ul><li><strong>BsTooltip</strong>: improve arrow positioning when activator width greater than tooltip width.</li><li><strong>AxiosPlugin</strong>: <ul><li>Expose <code>$http.patch</code> method.</li><li>Detect form object for data provided to the <code>$http.post</code>, <code>$http.patch</code>, <code>$http.put</code> methods and execute appropriate axios method.</li></ul></li></ul><h2 id="v2-1-4" tabindex="-1">v2.1.4 <a class="header-anchor" href="#v2-1-4" aria-label="Permalink to &quot;v2.1.4&quot;">​</a></h2><p>Released: December 28, 2024</p><h3>Improvements</h3><ul><li><strong>BsTooltip</strong>: <ul><li>Prevent displaying tooltip beyond the screen viewport by shifting its coordinates or reversing its placement.</li><li>Automatically adjust arrow positioning.</li></ul></li></ul><h2 id="v2-1-3" tabindex="-1">v2.1.3 <a class="header-anchor" href="#v2-1-3" aria-label="Permalink to &quot;v2.1.3&quot;">​</a></h2><p>Released: December 10, 2024</p><h3>Features &amp; Improvements</h3><ul><li><strong>BsNotification</strong>: <ul><li>Add feature to enable hiding the notification icon.</li><li>Improves initializing and removes unnecessary html element.</li><li>Improves the notification provider in handling and processing notification items.</li><li>Improves css variables and classes.</li></ul></li></ul><h2 id="v2-1-2" tabindex="-1">v2.1.2 <a class="header-anchor" href="#v2-1-2" aria-label="Permalink to &quot;v2.1.2&quot;">​</a></h2><p>Released: December 08, 2024</p><h3>Bug Fixes</h3><ul><li><strong>BsAppbarTitle</strong>: fixed bug incorrect left margin when placed as the first child of <code>&lt;BsAppbar&gt;</code>.</li><li><strong>BsBreadcrumb</strong>: fixed css variables.</li><li><strong>BsCheckboxGroup</strong>, <strong>BsRadioGroup</strong>: fixed column layout bug that did not respect the <code>column</code> property when its value was set to <code>1</code>.</li><li><strong>BsIconFontawesome</strong>: removed unused property and fixed typescript declaration.</li></ul><h2 id="v2-1-1" tabindex="-1">v2.1.1 <a class="header-anchor" href="#v2-1-1" aria-label="Permalink to &quot;v2.1.1&quot;">​</a></h2><p>Released: December 04, 2024</p><h3>Improvements</h3><ul><li><strong>BsColorPicker</strong>: rename property <code>outlineModeButton</code> to <code>modeButtonOutlined</code>.</li><li>Rename component <strong>BsFontAwesome</strong> to <strong>BsIconFontawesome</strong> for consistency.</li><li>Improve typescript doc comments.</li></ul><h3>Bug Fixes</h3><ul><li><strong>BsTooltip</strong>: fixed bug inconsistent arrow color.</li></ul><h2 id="v2-1-0" tabindex="-1">v2.1.0 <a class="header-anchor" href="#v2-1-0" aria-label="Permalink to &quot;v2.1.0&quot;">​</a></h2><p>Released: December 03, 2024</p><h3>Features &amp; Improvements</h3><ul><li>Migrate <strong>Google Material Icons</strong> to <strong><a href="https://fonts.google.com/icons?icon.set=Material+Symbols" target="_blank" rel="noreferrer">Google Material Symbols</a></strong>. This migration improve icon naming consistency, clarity and reduce the bundle size.</li><li>Migrate scss files from legacy SASS to modern SASS.</li><li>Reduce the number of color variants for each component on main css file (comply to <a href="https://getbootstrap.com/docs/5.2/getting-started/introduction/" target="_blank" rel="noreferrer">Bootstrap</a> colors with some addition) and put other color variants on different css file. This action greatly reduces the size of the main css file.</li><li>New components: <strong>BsFontAwesome</strong>, <strong>BsBreadcrumb</strong> and <strong>BsImageUploader</strong>.</li><li><strong>BsIcon</strong>, <strong>BsIconSvg</strong>, <strong>BsToggleIcon</strong>: <ul><li>Improve <code>icon</code> property to better accommodate <strong><em>Google Material Symbols</em></strong>.</li><li>Add new property <code>filled</code> to better accommodate <strong><em>Google Material Symbols</em></strong>.</li></ul></li><li><strong>BsAlert</strong>, <strong>BsChip</strong>, <strong>BsChipGroup</strong>: <ul><li>Improve <code>icon</code> property to better accommodate <strong><em>Google Material Symbols</em></strong>.</li><li>Improve <code>icon-variant</code> property to better accommodate <strong><em>Google Material Symbols</em></strong>.</li><li>Change the default value of the <code>icon-variant</code> property to <code>outlined</code>.</li></ul></li><li><strong>BsAvatar</strong>, <strong>BsTab</strong>, <strong>BsListTileLeading</strong>, <strong>BsListNavItem</strong>, <strong>BsButton</strong>, <strong>BsToggleButton</strong>, <strong>BsToggleField</strong>: <ul><li>Add new property <code>icon-variant</code> to better accommodate <strong><em>Google Material Symbols</em></strong>.</li><li>Improve <code>icon</code> property to better accommodate <strong><em>Google Material Symbols</em></strong>.</li></ul></li><li><strong>BsChipField</strong>, <strong>BsTextArea</strong>, <strong>BsTextField</strong>, <strong>BsNumericField</strong>, <strong>BsDateTimeField</strong>, <strong>BsCombobox</strong>: <ul><li>Improve properties: <code>append-icon</code>, <code>append-icon-outer</code>, <code>prepend-icon</code>, <code>prepend-icon-outer</code> and <code>action-icon-variant</code> to better accommodate <strong><em>Google Material Symbols</em></strong>.</li></ul></li></ul>',50)])])}const m=o(i,[["render",s]]);export{u as __pageData,m as default};
